unit Std.Tui.Chrome.CellGrid;

uses Std.Array, Std.Tui.Cells.Cell;

public type
  // Immutable rectangular grid of concrete or theme-resolved terminal cells.
  TuiCellGrid = record
    // Width in terminal cells.
    public Width: integer;
    // Height in terminal cells.
    public Height: integer;
    // Row-major terminal cells.
    public Cells: array of TuiCell;

    // Creates a row-major cell grid.
    //
    // Parameters:
    // - `Width`: Width in terminal cells.
    // - `Height`: Height in terminal cells.
    // - `Cells`: Row-major terminal cells used to populate the grid.
    public static function Create(Width: integer; Height: integer; Cells: array of TuiCell): TuiCellGrid;
    begin
      if (Width < 0) or (Height < 0) then
      begin
        panic('Tui cell grid dimensions must be non-negative')
      end;

      if Std.Array.Length(Cells) <> Width * Height then
      begin
        panic('Tui cell grid length must equal width times height')
      end;

      return record
        Width := Width;
        Height := Height;
        Cells := Cells;
      end
    end;
  end;

unit Std.Tui.Chrome.MenuQuery;

uses Std.Array, Std.Option, Std.Tui.Chrome.KeyGesture, Std.Tui.Chrome.MenuNode, Std.Tui.Ids.Action;

// Returns a menu node's identity.
//
// Parameters:
// - `Node`: Element or menu node processed by the operation.
public function TuiMenuNodeIdOf(Node: TuiMenuNode): TuiMenuNodeId;
begin
  case Node of
    TuiMenuNode.Command(Id, Parent, Text, Mnemonic, Action, Enabled, Shortcut):
    begin
      return Id
    end;
    TuiMenuNode.Submenu(Id, Parent, Text, Mnemonic, Enabled):
    begin
      return Id
    end;
    TuiMenuNode.Separator(Id, Parent):
    begin
      return Id
    end
  end
end;

// Returns a menu node's parent.
//
// Parameters:
// - `Node`: Element or menu node processed by the operation.
public function TuiMenuNodeParent(Node: TuiMenuNode): option of TuiMenuNodeId;
begin
  case Node of
    TuiMenuNode.Command(Id, Parent, Text, Mnemonic, Action, Enabled, Shortcut):
    begin
      return Parent
    end;
    TuiMenuNode.Submenu(Id, Parent, Text, Mnemonic, Enabled):
    begin
      return Parent
    end;
    TuiMenuNode.Separator(Id, Parent):
    begin
      return Parent
    end
  end
end;

// Returns a menu node's label, or an empty string for a separator.
//
// Parameters:
// - `Node`: Element or menu node processed by the operation.
public function TuiMenuNodeText(Node: TuiMenuNode): string;
begin
  case Node of
    TuiMenuNode.Command(Id, Parent, Text, Mnemonic, Action, Enabled, Shortcut):
    begin
      return Text
    end;
    TuiMenuNode.Submenu(Id, Parent, Text, Mnemonic, Enabled):
    begin
      return Text
    end;
    TuiMenuNode.Separator(Id, Parent):
    begin
      return ''
    end
  end
end;

// Returns a menu node's mnemonic, or an empty string for a separator.
//
// Parameters:
// - `Node`: Element or menu node processed by the operation.
public function TuiMenuNodeMnemonic(Node: TuiMenuNode): string;
begin
  case Node of
    TuiMenuNode.Command(Id, Parent, Text, Mnemonic, Action, Enabled, Shortcut):
    begin
      return Mnemonic
    end;
    TuiMenuNode.Submenu(Id, Parent, Text, Mnemonic, Enabled):
    begin
      return Mnemonic
    end;
    TuiMenuNode.Separator(Id, Parent):
    begin
      return ''
    end
  end
end;

// Reports whether a node can be selected.
//
// Parameters:
// - `Node`: Element or menu node processed by the operation.
public function TuiMenuNodeSelectable(Node: TuiMenuNode): boolean;
begin
  case Node of
    TuiMenuNode.Command(Id, Parent, Text, Mnemonic, Action, Enabled, Shortcut):
    begin
      return Enabled
    end;
    TuiMenuNode.Submenu(Id, Parent, Text, Mnemonic, Enabled):
    begin
      return Enabled
    end;
    TuiMenuNode.Separator(Id, Parent):
    begin
      return false
    end
  end
end;

// Reports whether a node opens a child menu.
//
// Parameters:
// - `Node`: Element or menu node processed by the operation.
public function TuiMenuNodeIsSubmenu(Node: TuiMenuNode): boolean;
begin
  case Node of
    TuiMenuNode.Submenu(Id, Parent, Text, Mnemonic, Enabled):
    begin
      return true
    end;
    TuiMenuNode.Command(Id, Parent, Text, Mnemonic, Action, Enabled, Shortcut):
    begin
      return false
    end;
    TuiMenuNode.Separator(Id, Parent):
    begin
      return false
    end
  end
end;

// Returns a command action when the node is a command.
//
// Parameters:
// - `Node`: Element or menu node processed by the operation.
public function TuiMenuNodeAction(Node: TuiMenuNode): option of TuiAction;
begin
  case Node of
    TuiMenuNode.Command(Id, Parent, Text, Mnemonic, Action, Enabled, Shortcut):
    begin
      return Some(Action)
    end;
    TuiMenuNode.Submenu(Id, Parent, Text, Mnemonic, Enabled):
    begin
      return None
    end;
    TuiMenuNode.Separator(Id, Parent):
    begin
      return None
    end
  end
end;

// Returns a command shortcut when present.
//
// Parameters:
// - `Node`: Element or menu node processed by the operation.
public function TuiMenuNodeShortcut(Node: TuiMenuNode): option of TuiKeyGesture;
begin
  case Node of
    TuiMenuNode.Command(Id, Parent, Text, Mnemonic, Action, Enabled, Shortcut):
    begin
      return Shortcut
    end;
    TuiMenuNode.Submenu(Id, Parent, Text, Mnemonic, Enabled):
    begin
      return None
    end;
    TuiMenuNode.Separator(Id, Parent):
    begin
      return None
    end
  end
end;

// Finds a node index by identity, or returns `-1`.
//
// Parameters:
// - `Nodes`: Flat ordered menu-node collection.
// - `Id`: Identifier assigned to the created or selected value.
public function TuiMenuFind(Nodes: array of TuiMenuNode; Id: TuiMenuNodeId): integer;
begin
  for Index: integer := 0 to Std.Array.Length(Nodes) - 1 do
  begin
    if TuiMenuNodeIdOf(Nodes[Index]).Value = Id.Value then
    begin
      return Index
    end
  end;

  return -1
end;

// Reports whether a node has the supplied parent.
//
// Parameters:
// - `Node`: Element or menu node processed by the operation.
// - `Parent`: Optional parent menu-node identifier.
public function TuiMenuHasParent(Node: TuiMenuNode; Parent: option of TuiMenuNodeId): boolean;
begin
  case TuiMenuNodeParent(Node) of
    Some(NodeParent):
    begin
      case Parent of
        Some(Expected):
        begin
          return NodeParent.Value = Expected.Value
        end;
        None:
        begin
          return false
        end
      end
    end;
    None:
    begin
      case Parent of
        Some(Expected):
        begin
          return false
        end;
        None:
        begin
          return true
        end
      end
    end
  end
end;

// Returns the first selectable child of a parent.
//
// Parameters:
// - `Nodes`: Flat ordered menu-node collection.
// - `Parent`: Optional parent menu-node identifier.
public function TuiMenuFirstSelectable(Nodes: array of TuiMenuNode; Parent: option of TuiMenuNodeId): option of TuiMenuNodeId;
begin
  for Index: integer := 0 to Std.Array.Length(Nodes) - 1 do
  begin
    if TuiMenuHasParent(Nodes[Index], Parent) and TuiMenuNodeSelectable(Nodes[Index]) then
    begin
      return Some(TuiMenuNodeIdOf(Nodes[Index]))
    end
  end;

  return None
end;

// Returns the next selectable sibling, wrapping in the requested direction.
//
// Parameters:
// - `Nodes`: Flat ordered menu-node collection.
// - `Current`: Current extent used by the calculation.
// - `Direction`: Direction of the requested movement.
public function TuiMenuNextSelectable(
  Nodes: array of TuiMenuNode;
  Current: TuiMenuNodeId;
  Direction: integer
): option of TuiMenuNodeId;
begin
  var CurrentIndex: integer := TuiMenuFind(Nodes, Current);
  if CurrentIndex < 0 then
  begin
    return None
  end;
  var Parent: option of TuiMenuNodeId := TuiMenuNodeParent(Nodes[CurrentIndex]);
  mutable var Siblings: array of TuiMenuNodeId := [];
  for Index: integer := 0 to Std.Array.Length(Nodes) - 1 do
  begin
    if TuiMenuHasParent(Nodes[Index], Parent) and TuiMenuNodeSelectable(Nodes[Index]) then
    begin
      Std.Array.Push(Siblings, TuiMenuNodeIdOf(Nodes[Index]))
    end
  end;

  if Std.Array.Length(Siblings) = 0 then
  begin
    return None
  end;
  mutable var Position: integer := 0;
  for Index: integer := 0 to Std.Array.Length(Siblings) - 1 do
  begin
    if Siblings[Index].Value = Current.Value then
    begin
      Position := Index
    end
  end;

  Position := Position + Direction;
  if Position < 0 then
  begin
    Position := Std.Array.Length(Siblings) - 1
  end
  else if Position >= Std.Array.Length(Siblings) then
  begin
    Position := 0
  end;

  return Some(Siblings[Position])
end;

// Returns the root ancestor of one node.
//
// Parameters:
// - `Nodes`: Flat ordered menu-node collection.
// - `Id`: Identifier assigned to the created or selected value.
public function TuiMenuRootOf(Nodes: array of TuiMenuNode; Id: TuiMenuNodeId): option of TuiMenuNodeId;
begin
  mutable var Current: TuiMenuNodeId := Id;
  mutable var Remaining: integer := Std.Array.Length(Nodes) + 1;
  while Remaining > 0 do
  begin
    Remaining := Remaining - 1;
    var Index: integer := TuiMenuFind(Nodes, Current);
    if Index < 0 then
    begin
      return None
    end;

    case TuiMenuNodeParent(Nodes[Index]) of
      Some(Parent):
      begin
        Current := Parent
      end;
      None:
      begin
        return Some(Current)
      end
    end
  end;

  return None
end;

unit Std.Tui.Geometry.Rect;

uses Std.Tui.Geometry.Point, Std.Tui.Geometry.Size;

public const
  // Largest integer used for checked rectangle-edge calculations.
  TuiRectIntegerMax: integer := 9223372036854775807;

function TuiRectRequireNonNegative(Value: integer; Name: string): integer;
begin
  if Value < 0 then
  begin
    panic(('Tui ' + Name) + ' must not be negative')
  end;

  return Value
end;

function TuiRectCheckedEdge(Origin: integer; Extent: integer; Name: string): integer;
begin
  if Origin > TuiRectIntegerMax - Extent then
  begin
    panic(('Tui ' + Name) + ' edge overflows integer coordinates')
  end;

  return Origin + Extent
end;

function TuiRectExtentFromEdges(Origin: integer; Edge: integer; Name: string): integer;
begin
  if Edge < Origin then
  begin
    panic(('Tui ' + Name) + ' edge precedes its origin')
  end;

  if (Origin < 0) and (Edge > TuiRectIntegerMax + Origin) then
  begin
    panic(('Tui ' + Name) + ' extent overflows integer coordinates')
  end;

  return Edge - Origin
end;

function TuiRectMin(Left: integer; Right: integer): integer;
begin
  if Left < Right then
  begin
    return Left
  end;

  return Right
end;

function TuiRectMax(Left: integer; Right: integer): integer;
begin
  if Left > Right then
  begin
    return Left
  end;

  return Right
end;

public type
  // Zero-based half-open terminal-cell rectangle (`right = x + width`).
  TuiRect = record
    // Zero-based horizontal terminal-cell coordinate.
    public X: integer;
    // Zero-based vertical terminal-cell coordinate.
    public Y: integer;
    // Width in terminal cells.
    public Width: integer;
    // Height in terminal cells.
    public Height: integer;

    // Creates a rectangle and rejects negative or overflowing extents.
    //
    // Parameters:
    // - `X`: Zero-based horizontal terminal-cell coordinate.
    // - `Y`: Zero-based vertical terminal-cell coordinate.
    // - `Width`: Width in terminal cells.
    // - `Height`: Height in terminal cells.
    public static function Create(X: integer; Y: integer; Width: integer; Height: integer): TuiRect;
    begin
      TuiRectRequireNonNegative(Width, 'width');
      TuiRectRequireNonNegative(Height, 'height');
      TuiRectCheckedEdge(X, Width, 'right');
      TuiRectCheckedEdge(Y, Height, 'bottom');
      return record
        X := X;
        Y := Y;
        Width := Width;
        Height := Height;
      end
    end;

    // Creates a rectangle from exclusive edges.
    //
    // Parameters:
    // - `Left`: Left input value or edge.
    // - `Top`: Top edge or margin.
    // - `Right`: Right input value or edge.
    // - `Bottom`: Bottom edge or margin.
    public static function FromEdges(Left: integer; Top: integer; Right: integer; Bottom: integer): TuiRect;
    begin
      var Width: integer := TuiRectExtentFromEdges(Left, Right, 'right');
      var Height: integer := TuiRectExtentFromEdges(Top, Bottom, 'bottom');
      return TuiRect.Create(Left, Top, Width, Height)
    end;

    // Creates a rectangle from a point and size.
    //
    // Parameters:
    // - `Position`: Position in terminal-cell coordinates.
    // - `Size`: Size in terminal cells.
    public static function FromPointSize(Position: TuiPoint; Size: TuiSize): TuiRect;
    begin
      return TuiRect.Create(Position.X, Position.Y, Size.Width, Size.Height)
    end;

    // Creates a rectangle from exclusive corners.
    //
    // Parameters:
    // - `TopLeft`: Top-left corner of the rectangle.
    // - `BottomRight`: Bottom-right corner of the rectangle.
    public static function FromCorners(TopLeft: TuiPoint; BottomRight: TuiPoint): TuiRect;
    begin
      return TuiRect.FromEdges(TopLeft.X, TopLeft.Y, BottomRight.X, BottomRight.Y)
    end;

    // Returns the first column after the rectangle.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    public function Right(Self: TuiRect): integer;
    begin
      return TuiRectCheckedEdge(Self.X, Self.Width, 'right')
    end;

    // Returns the first row after the rectangle.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    public function Bottom(Self: TuiRect): integer;
    begin
      return TuiRectCheckedEdge(Self.Y, Self.Height, 'bottom')
    end;

    // Returns whether the rectangle has no drawable cells.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    public function IsEmpty(Self: TuiRect): boolean;
    begin
      return (Self.Width = 0) or (Self.Height = 0)
    end;

    // Returns whether the half-open rectangle contains the point.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Point`: Point tested by the operation.
    public function Contains(Self: TuiRect; Point: TuiPoint): boolean;
    begin
      return (((Point.X >= Self.X) and (Point.X < Self.Right())) and (Point.Y >= Self.Y)) and
             (Point.Y < Self.Bottom())
    end;

    // Returns whether two rectangles share any cell.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Other`: Other rectangle or value used for comparison.
    public function Intersects(Self: TuiRect; Other: TuiRect): boolean;
    begin
      return (((Self.X < Other.Right()) and (Other.X < Self.Right())) and (Self.Y < Other.Bottom())) and
             (Other.Y < Self.Bottom())
    end;

    // Returns the overlapping rectangle, or an empty rectangle at the clamped origin.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    // - `Other`: Other rectangle or value used for comparison.
    public function Intersect(Self: TuiRect; Other: TuiRect): TuiRect;
    begin
      var X: integer := TuiRectMax(Self.X, Other.X);
      var Y: integer := TuiRectMax(Self.Y, Other.Y);
      var Right: integer := TuiRectMin(Self.Right(), Other.Right());
      var Bottom: integer := TuiRectMin(Self.Bottom(), Other.Bottom());
      if (Right <= X) or (Bottom <= Y) then
      begin
        return TuiRect.Create(X, Y, 0, 0)
      end;

      return TuiRect.Create(X, Y, Right - X, Bottom - Y)
    end;

    // Returns a rectangle inset by one cell on every side.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    public function Inset(Self: TuiRect): TuiRect;
    begin
      mutable var InnerWidth: integer := Self.Width - 2;
      mutable var InnerHeight: integer := Self.Height - 2;
      if InnerWidth < 0 then
      begin
        InnerWidth := 0
      end;

      if InnerHeight < 0 then
      begin
        InnerHeight := 0
      end;

      return TuiRect.Create(Self.X + 1, Self.Y + 1, InnerWidth, InnerHeight)
    end;
  end;

// Creates a full-surface rectangle at the origin.
//
// Parameters:
// - `Size`: Size in terminal cells.
public function TuiRectForSize(Size: TuiSize): TuiRect;
begin
  return TuiRect.Create(0, 0, Size.Width, Size.Height)
end;

unit Std.Tui.Layout.LayoutFit;

uses Std.Tui.Geometry.Size;

function TuiLayoutFitOverflow(Minimum: integer; Available: integer): integer;
begin
  if Minimum > Available then
  begin
    return Minimum - Available
  end;

  return 0
end;

public type
  // Reports whether allocated bounds satisfy a measured minimum.
  TuiLayoutFit = record
    // Minimum value or size.
    public Minimum: TuiSize;
    // Available terminal size.
    public Available: TuiSize;
    // Amount by which the minimum size exceeds the available size.
    public Overflow: TuiSize;

    // Creates a fit report from minimum and available sizes.
    //
    // Parameters:
    // - `Minimum`: Minimum accepted value or extent.
    // - `Available`: Available terminal size.
    public static function Create(Minimum: TuiSize; Available: TuiSize): TuiLayoutFit;
    begin
      return record
        Minimum := Minimum;
        Available := Available;
        Overflow := TuiSize.Create(TuiLayoutFitOverflow(Minimum.Width, Available.Width), TuiLayoutFitOverflow(Minimum.Height, Available.Height));
      end
    end;

    // Returns whether neither axis overflows.
    //
    // Parameters:
    // - `Self`: Receiver value operated on by the method.
    public function Fits(Self: TuiLayoutFit): boolean;
    begin
      return (Self.Overflow.Width = 0) and (Self.Overflow.Height = 0)
    end;
  end;

// Compact dashboard-gauge painting.
unit Std.Tui.Rendering.Gauge;

uses
  Std.Console, Std.Conv, Std.Tui.Cells.Cell, Std.Tui.Cells.StyleRole, Std.Tui.Chrome.Gauge,
  Std.Tui.Geometry.Point, Std.Tui.Geometry.Rect, Std.Tui.Rendering.Canvas;

// Paints a label, bounded bar, and percentage on one row.
//
// Parameters:
// - `Canvas`: Canvas that receives the drawing operation.
// - `Bounds`: Rectangle affected by the operation.
// - `Gauge`: Gauge specification to paint.
public procedure TuiPaintGauge(Canvas: TuiCanvas; Bounds: TuiRect; Gauge: TuiGauge);
begin
  if Bounds.IsEmpty() then
  begin
    return
  end;
  var LabelWidth: integer := Std.Console.DisplayWidth(Gauge.LabelText);
  var Percent: integer := (Gauge.Value * 100) div Gauge.Maximum;
  var PercentText: string := Std.Conv.IntToStr(Percent) + '%';
  var PercentWidth: integer := Std.Console.DisplayWidth(PercentText);
  mutable var BarWidth: integer := ((Bounds.Width - LabelWidth) - PercentWidth) - 4;
  if BarWidth < 1 then
  begin
    BarWidth := 1
  end;
  var BarX: integer := (Bounds.X + LabelWidth) + 2;
  var FillWidth: integer := (BarWidth * Gauge.Value) div Gauge.Maximum;
  Canvas.FillRect(Bounds, TuiCell.Create(' ', TuiStyleRole.Normal));
  Canvas.WriteText(TuiPoint.Create(Bounds.X, Bounds.Y), Gauge.LabelText, TuiStyleRole.Normal);
  Canvas.DrawHorizontalLine(BarX, Bounds.Y, BarWidth, TuiStyleRole.GaugeTrack);
  Canvas.DrawHorizontalLine(BarX, Bounds.Y, FillWidth, TuiStyleRole.GaugeFill);
  Canvas.WriteText(TuiPoint.Create(Bounds.Right() - PercentWidth, Bounds.Y), PercentText, TuiStyleRole.Accent)
end;

// Separator-rule painting.
unit Std.Tui.Rendering.Rule;

uses
  Std.Tui.Cells.StyleRole, Std.Tui.Geometry.Point, Std.Tui.Geometry.Rect, Std.Tui.Rendering.Canvas;

// Paints a thin horizontal separator with optional left-aligned text.
//
// Parameters:
// - `Canvas`: Canvas that receives the drawing operation.
// - `Bounds`: Rectangle affected by the operation.
// - `Text`: Text processed or displayed by the operation.
public procedure TuiPaintRule(Canvas: TuiCanvas; Bounds: TuiRect; Text: string);
begin
  if Bounds.IsEmpty() then
  begin
    return
  end;

  Canvas.DrawHorizontalLine(Bounds.X, Bounds.Y, Bounds.Width, TuiStyleRole.Rule);
  if (Text <> '') and (Bounds.Width > 4) then
  begin
    Canvas.Child(TuiRect.Create(Bounds.X + 2, Bounds.Y, Bounds.Width - 4, 1))
      .WriteText(TuiPoint.Create(0, 0), (' ' + Text) + ' ', TuiStyleRole.Title)
  end
end;

unit Std.Tui.Runtime.Routing.MenuPointer;

uses
  Std.Array, Std.Console, Std.Tui.Chrome.MenuGeometry, Std.Tui.Chrome.MenuNode,
  Std.Tui.Chrome.MenuQuery, Std.Tui.Elements.Element, Std.Tui.Geometry.Point, Std.Tui.Geometry.Rect,
  Std.Tui.Ids.Action, Std.Tui.Ids.ControlId, Std.Tui.Layout.Frame, Std.Tui.Runtime.Msg,
  Std.Tui.Runtime.Routing.Focus;

public type
  // Controlled menu and arranged bar bounds used by pointer routing.
  TuiPointerMenu = record
    // Stable identifier of the value.
    public Id: TuiControlId;
    // Flat ordered menu-node collection.
    public Nodes: array of TuiMenuNode;
    // Controlled menu state.
    public State: TuiMenuState;
    // Action emitted when the controlled value changes.
    public ChangeAction: TuiAction;
    // Rectangle occupied by the value.
    public Bounds: TuiRect;
  end;

mutable var
  TuiPointerMenus: array of TuiPointerMenu := [];

function TuiPointerMenuWalk(
  Frame: TuiArrangedFrame;
  Node: TuiElement;
  Index: integer;
  AllowMenu: boolean
): integer;
begin
  mutable var Next: integer := Index + 1;
  case Node of
    TuiElement.Menu(Id, Nodes, State, ChangeAction):
    begin
      if AllowMenu then
      begin
        mutable var Menus: array of TuiPointerMenu := TuiPointerMenus;
        TuiPointerMenus := [];
        Std.Array.Push(Menus, record
          Id := Id;
          Nodes := Nodes;
          State := State;
          ChangeAction := ChangeAction;
          Bounds := Frame.EntryAt(Index).Bounds;
        end);
        TuiPointerMenus := Menus
      end
    end;
    TuiElement.Desktop(Focused, Children):
    begin
      mutable var ModalIndex: integer := -1;
      for ChildIndex: integer := 0 to Std.Array.Length(Children) - 1 do
      begin
        case Children[ChildIndex] of
          TuiElement.Overlay(Title, OverlayChildren):
          begin
            ModalIndex := ChildIndex
          end
          else
          begin
          end
        end
      end;

      for ChildIndex: integer := 0 to Std.Array.Length(Children) - 1 do
      begin
        Next := TuiPointerMenuWalk(Frame, Children[ChildIndex], Next, AllowMenu and
                                                                      ((ModalIndex < 0) or (ModalIndex = ChildIndex)))
      end
    end;
    TuiElement.Scroll(Id, Offset, ChangeAction, Children):
    begin
      for ChildIndex: integer := 0 to Std.Array.Length(Children) - 1 do
      begin
        Next := TuiPointerMenuWalk(Frame, Children[ChildIndex], Next, AllowMenu)
      end
    end;
    TuiElement.Row(Children, Spacing):
    begin
      for ChildIndex: integer := 0 to Std.Array.Length(Children) - 1 do
      begin
        Next := TuiPointerMenuWalk(Frame, Children[ChildIndex], Next, AllowMenu)
      end
    end;
    TuiElement.Column(Children, Spacing):
    begin
      for ChildIndex: integer := 0 to Std.Array.Length(Children) - 1 do
      begin
        Next := TuiPointerMenuWalk(Frame, Children[ChildIndex], Next, AllowMenu)
      end
    end;
    TuiElement.Layout(Settings, Children):
    begin
      for ChildIndex: integer := 0 to Std.Array.Length(Children) - 1 do
      begin
        Next := TuiPointerMenuWalk(Frame, Children[ChildIndex], Next, AllowMenu)
      end
    end;
    TuiElement.Panel(Title, Children):
    begin
      for ChildIndex: integer := 0 to Std.Array.Length(Children) - 1 do
      begin
        Next := TuiPointerMenuWalk(Frame, Children[ChildIndex], Next, AllowMenu)
      end
    end;
    TuiElement.Overlay(Title, Children):
    begin
      for ChildIndex: integer := 0 to Std.Array.Length(Children) - 1 do
      begin
        Next := TuiPointerMenuWalk(Frame, Children[ChildIndex], Next, AllowMenu)
      end
    end
    else
    begin
    end
  end;

  return Next
end;

function TuiPointerMenuFocus(Root: TuiElement; Menu: TuiPointerMenu): array of TuiMsg;
begin
  var Previous: option of TuiControlId := TuiRootFocus(Root);
  if TuiFocusMatches(Previous, Menu.Id) then
  begin
    return []
  end;

  return [TuiMsg.FocusChanged(Previous, Some(Menu.Id))]
end;

function TuiPointerMenuHover(Menu: TuiPointerMenu; Id: TuiMenuNodeId): array of TuiMsg;
begin
  case Menu.State.Active of
    Some(Active):
    begin
      if Active.Value = Id.Value then
      begin
        return []
      end
    end;
    None:
    begin
    end
  end;

  return [TuiMsg.MenuChanged(Menu.Id, Menu.ChangeAction, TuiMenuState.OpenAt(Id))]
end;

function TuiPointerMenuBarHit(
  Root: TuiElement;
  Menu: TuiPointerMenu;
  Point: TuiPoint;
  Activate: boolean
): option of array of TuiMsg;
begin
  if not TuiRect.Create(Menu.Bounds.X, Menu.Bounds.Y, Menu.Bounds.Width, 1).Contains(Point) then
  begin
    return None
  end;
  mutable var X: integer := Menu.Bounds.X;
  for Index: integer := 0 to Std.Array.Length(Menu.Nodes) - 1 do
  begin
    case TuiMenuNodeParent(Menu.Nodes[Index]) of
      Some(Parent):
      begin
      end;
      None:
      begin
        var Width: integer := Std.Console.DisplayWidth(TuiMenuNodeText(Menu.Nodes[Index])) + 2;
        if TuiRect.Create(X, Menu.Bounds.Y, Width, 1).Contains(Point) and
           TuiMenuNodeSelectable(Menu.Nodes[Index]) then
        begin
          if not Activate then
          begin
            return Some(TuiPointerMenuHover(Menu, TuiMenuNodeIdOf(Menu.Nodes[Index])))
          end;

          return Some(Std.Array.Concat(TuiPointerMenuFocus(Root, Menu), [
                                                                          TuiMsg.MenuChanged(Menu.Id, Menu.ChangeAction, TuiMenuState.OpenAt(TuiMenuNodeIdOf(Menu.Nodes[Index])))
                                                                        ]))
        end;

        X := X + Width
      end
    end
  end;

  return Some([])
end;

function TuiPointerMenuPopupHit(
  Menu: TuiPointerMenu;
  Point: TuiPoint;
  TerminalBounds: TuiRect;
  Activate: boolean
): option of array of TuiMsg;
begin
  var Popups: array of TuiMenuPopup := TuiMenuPopupGeometry(Menu.Nodes, Menu.State, Menu.Bounds, TerminalBounds);
  for PopupIndex: integer := Std.Array.Length(Popups) - 1 downto 0 do
  begin
    if Popups[PopupIndex].Bounds.Contains(Point) then
    begin
      var Row: integer := (Point.Y - Popups[PopupIndex].Bounds.Y) - 1;
      if (Row < 0) or (Row >= Popups[PopupIndex].Bounds.Height - 2) then
      begin
        return Some([])
      end;
      mutable var ChildRow: integer := 0;
      for Index: integer := 0 to Std.Array.Length(Menu.Nodes) - 1 do
      begin
        if TuiMenuHasParent(Menu.Nodes[Index], Some(Popups[PopupIndex].Parent)) then
        begin
          if ChildRow = Row then
          begin
            if not TuiMenuNodeSelectable(Menu.Nodes[Index]) then
            begin
              return Some([])
            end;

            if TuiMenuNodeIsSubmenu(Menu.Nodes[Index]) then
            begin
              if not Activate then
              begin
                return Some(TuiPointerMenuHover(Menu, TuiMenuNodeIdOf(Menu.Nodes[Index])))
              end;

              return Some([
                            TuiMsg.MenuChanged(Menu.Id, Menu.ChangeAction, TuiMenuState.OpenAt(TuiMenuNodeIdOf(Menu.Nodes[Index])))
                          ])
            end;

            if not Activate then
            begin
              return Some(TuiPointerMenuHover(Menu, TuiMenuNodeIdOf(Menu.Nodes[Index])))
            end;

            case TuiMenuNodeAction(Menu.Nodes[Index]) of
              Some(Action):
              begin
                return Some([
                              TuiMsg.MenuChanged(Menu.Id, Menu.ChangeAction, TuiMenuState.Closed()),
                              TuiMsg.Action(Menu.Id, Action)
                            ])
              end;
              None:
              begin
                return Some([])
              end
            end
          end;

          ChildRow := ChildRow + 1
        end
      end;

      return Some([])
    end
  end;

  return None
end;

// Routes a left-button press or movement over one active hierarchical menu.
//
// Parameters:
// - `Root`: Root of the element tree.
// - `Frame`: Arranged frame containing element geometry.
// - `Point`: Point tested by the operation.
// - `Activate`: Whether the control is activated by the operation.
public function TuiRouteMenuPointer(
  Root: TuiElement;
  Frame: TuiArrangedFrame;
  Point: TuiPoint;
  Activate: boolean
): option of array of TuiMsg;
begin
  TuiPointerMenus := [];
  if TuiPointerMenuWalk(Frame, Root, 0, true) <> Frame.Count() then
  begin
    panic('Tui menu pointer routing did not consume the complete arranged frame')
  end;

  if Std.Array.Length(TuiPointerMenus) = 0 then
  begin
    return None
  end;
  var Menu: TuiPointerMenu := TuiPointerMenus[0];
  if not Activate and not Menu.State.Open then
  begin
    return None
  end;

  case TuiPointerMenuBarHit(Root, Menu, Point, Activate) of
    Some(Messages):
    begin
      return Some(Messages)
    end;
    None:
    begin
    end
  end;

  if Menu.State.Open then
  begin
    case TuiPointerMenuPopupHit(Menu, Point, Frame.EntryAt(0).Bounds, Activate) of
      Some(Messages):
      begin
        return Some(Messages)
      end;
      None:
      begin
        if not Activate then
        begin
          return Some([])
        end;

        return Some([TuiMsg.MenuChanged(Menu.Id, Menu.ChangeAction, TuiMenuState.Closed())])
      end
    end
  end;

  return None
end;

